// leapyear.cpp - Check leap year
#include <iostream>
using namespace std;

int main() {
    int year;
    cout << "Enter a year: ";
    cin >> year;

    if ((year % 400 == 0) || (year % 4 == 0 && year % 100 != 0))
        cout << year << " is a leap year." << endl;
    else
        cout << year << " is not a leap year." << endl;
    return 0;
}

// electricity.cpp - Electricity bill using else-if ladder
#include <iostream>
using namespace std;

int main() {
    int units;
    float bill;
    cout << "Enter units consumed: ";
    cin >> units;

    if (units <= 100)
        bill = units * 4.0;
    else if (units <= 200)
        bill = 100 * 4.0 + (units - 100) * 5.5;
    else if (units <= 300)
        bill = 100 * 4.0 + 100 * 5.5 + (units - 200) * 7.0;
    else
        bill = 100 * 4.0 + 100 * 5.5 + 100 * 7.0 + (units - 300) * 8.5;

    cout << "Total bill = Rs " << bill << endl;
    return 0;
}

