// menu.cpp - Menu-driven program using do-while
#include <iostream>
using namespace std;

int main() {
    int choice;
    do {
        cout << "\n--- MENU ---" << endl;
        cout << "1. Square of a number" << endl;
        cout << "2. Cube of a number" << endl;
        cout << "3. Exit" << endl;
        cout << "Enter choice: ";
        cin >> choice;

        if (choice == 1 || choice == 2) {
            int n;
            cout << "Enter number: ";
            cin >> n;
            if (choice == 1) cout << "Square = " << n * n << endl;
            else             cout << "Cube = " << n * n * n << endl;
        } else if (choice != 3) {
            cout << "Invalid choice!" << endl;
        }
    } while (choice != 3);

    cout << "Thank you!" << endl;
    return 0;
}

// continue.cpp - break and continue
#include <iostream>
using namespace std;

int main() {
    cout << "Odd numbers from 1 to 15, stop at 11:" << endl;
    for (int i = 1; i <= 15; i++) {
        if (i % 2 == 0)
            continue;   // skip even numbers
        if (i > 11)
            break;      // leave the loop
        cout << i << " ";
    }
    cout << endl;
    return 0;
}

// prime.cpp - Check prime using a loop and break
#include <iostream>
using namespace std;

int main() {
    int n;
    bool isPrime = true;
    cout << "Enter a number: ";
    cin >> n;

    if (n < 2) isPrime = false;
    for (int i = 2; i * i <= n; i++) {
        if (n % i == 0) {
            isPrime = false;
            break;          // no need to check further
        }
    }

    if (isPrime) cout << n << " is prime." << endl;
    else         cout << n << " is not prime." << endl;
    return 0;
}

// patterns.cpp - Nested loop patterns
#include <iostream>
using namespace std;

int main() {
    int n = 5;
    cout << "Pattern 1:" << endl;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++)
            cout << "* ";
        cout << endl;
    }

    cout << "Pattern 2:" << endl;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= i; j++)
            cout << j << " ";
        cout << endl;
    }

    cout << "Pattern 3 (pyramid):" << endl;
    for (int i = 1; i <= n; i++) {
        for (int s = 1; s <= n - i; s++)
            cout << " ";
        for (int j = 1; j <= 2 * i - 1; j++)
            cout << "*";
        cout << endl;
    }
    return 0;
}

// fibonacci.cpp - First n Fibonacci terms
#include <iostream>
using namespace std;

int main() {
    int n;
    cout << "How many terms? ";
    cin >> n;

    long long a = 0, b = 1;
    for (int i = 1; i <= n; i++) {
        cout << a << " ";
        long long next = a + b;
        a = b;
        b = next;
    }
    cout << endl;
    return 0;
}

// armstrong.cpp - Armstrong numbers from 100 to 999
#include <iostream>
using namespace std;

int main() {
    cout << "3-digit Armstrong numbers: ";
    for (int n = 100; n <= 999; n++) {
        int temp = n, sum = 0;
        while (temp > 0) {
            int d = temp % 10;
            sum += d * d * d;
            temp /= 10;
        }
        if (sum == n)
            cout << n << " ";
    }
    cout << endl;
    return 0;
}

